## Why This Is Asked

Tests ability to bridge C callbacks into Go safely, with memory management, backpressure, and multi-threaded execution. Elicits decisions about arena reuse, finalizers, and error propagation across language boundaries.

## Key Concepts

- CGO callbacks and cross-language control flow
- Memory ownership between C and Go (arena reuse, finalizers)
- cgo.Handle and //export for callbacks
- Backpressure handling in a Go worker pool

## Code Example

```c
// header: streaming.h
#ifndef STREAMING_H
#define STREAMING_H
#include <stddef.h>

typedef void (*event_cb)(const char* json_batch, void* ctx);
void register_event_source(event_cb cb, void* ctx);
void start_streaming(size_t batch_size, size_t max_events);
#endif
```

```c
// minimal_impl.c
#include "streaming.h"
#include <stdlib.h>

static event_cb s_cb = NULL;
static void* s_ctx = NULL;

void register_event_source(event_cb cb, void* ctx){ s_cb = cb; s_ctx = ctx; }

void start_streaming(size_t batch_size, size_t max_events){
    // simple mock: emit a single batch then stop
    if(!s_cb) return;
    // allocate batch buffer (arena-like)
    const char* batch = "[{\"ev\":1}]";
    s_cb(batch, s_ctx);
}
```

```go
// binding.go
package streaming
// #include "streaming.h"
import "C"
import (
    "runtime"
    "sync"
    "unsafe"
)

type EventCallback func(string) error

var (
    callbacks   = make(map[uintptr]EventCallback)
    cbMu        sync.Mutex
)

//export goEventCallback
func goEventCallback(cBatch *C.char, ctx unsafe.Pointer) {
    id := uintptr(ctx)
    cbMu.Lock()
    cb := callbacks[id]
    cbMu.Unlock()
    if cb == nil {
        return
    }
    batch := C.GoString(cBatch)
    _ = cb(batch)
}

func StartStream(batchSize int, onEvent EventCallback) error {
    // store callback and start streaming
    id := uintptr(unsafe.Pointer(&onEvent))
    cbMu.Lock()
    callbacks[id] = onEvent
    cbMu.Unlock()
    C.register_event_source(C.event_cb(C.goEventCallback), unsafe.Pointer(id))
    C.start_streaming(C.size_t(batchSize), C.size_t(batchSize))
    runtime.KeepAlive(onEvent)
    return nil
}
```

```go
// main.go
package main

import (
    "fmt"
    sc "example/streaming" // adjust import path as needed
    "sync/atomic"
)

func main() {
    var events int32
    _ = sc.StartStream(64, func(batch string) error {
        atomic.AddInt32(&events, 1)
        // process batch
        fmt.Println("received", batch)
        return nil
    })
    // wait/flush logic as needed
}
```

